android.extraProguardRules:
-dontwarn javax.lang.model.**
-keepclassmembers class * extends com.google.protobuf.GeneratedMessageLite {
  <fields>;
}
# MediaPipe laedt seine Java-Klassen aus nativem Code ueber deren NAMEN
# (FindClass/GetMethodID). R8 sieht diese Referenzen nicht, benennt die
# Klassen um, und libmediapipe_tasks_jni.so bekommt beim Start des Graphen
# java_class == null zurueck -- der JNI-Check bricht daraufhin den ganzen
# Prozess mit SIGABRT ab. Auf dem Geraet als Absturz beim Handflaechen-
# Schritt sichtbar geworden, sobald der Release-Build zum ersten Mal
# ueberhaupt durch R8 kam.
-keep class com.google.mediapipe.** { *; }
-dontwarn com.google.mediapipe.**

# MediaPipe reicht Protobuf-Nachrichten ueber dieselbe JNI-Grenze.
-keep class com.google.protobuf.** { *; }

# Allgemein: jede Klasse, die native Methoden deklariert, muss ihren Namen
# behalten -- sonst findet der native Gegenpart sie nicht mehr.
-keepclasseswithmembernames,includedescriptorclasses class * {
  native <methods>;
}
